        '19925',
        'AML user permission',
        'Following the review and verification of the access rights for the Officer, Senior, and Manager levels, we have identified several discrepancies when compared to the officially approved access matrix.  1. Officer Level    We found two functions assigned to Officers that are not aligned with their approved access rights:    •Case Management (Offline Screening) is Added to the officer level.    •Case Management (Online Screening) is Added to the officer level.    2. Senior Level    For the Senior level, the following issues were identified:    •Access to Delete and Delete All functions, which are not part of the approved permissions.    •Case Management (Offline Screening) is Added to the senior position .    •Case Management (Online Screening) is Added to the senior position.    These items are highlighted in red in the attached file for your reference.    3. Manager Level    For the Manager level, we found the following mismatches:    •Access related to Approval, Update, and View does not fully align with the approved access rights.    In addition, Managers have access to:    •Case Management (Offline Screening) is Added to the Manager position.    •Case Management (Online Screening) is Added to the Manager position.  which are not within the authorized scope for this level.    All discrepancies are clearly marked in red in the attached file.    We would appreciate clarification regarding the business need for All Position to access these functions.    Please provide us with list of users who have access on AML Database and OS',
