        'Change IP',
        'Dear Pio-tech Team,  Greetings,    Kindly be informed that we upgrade core banking system, and change the live production core banking DB server on this IP 10.130.20.121  And test core banking DB server on this IP 10.130.30.132.  So if you need any addition information from our side to makes your changes don’t hesitate.  Regards,',
        'Dear Zeina,    Based on our web session, kindly be informed that the new IP address for the core production database has been configured successfully. I also executed the daily fill for September 25, 2025, and it completed successfully.    Regarding the report issue, please note that the report is reading directly from the core database. Therefore, we kindly request you to open the connection between the core production database and the application production server in order to resolve this issue.    Therefore, we will consider this case closed.    Best Regards,',
