        'Workflow issue',
        'The appearance of alerts that do not concern branch customers is a recurring problem that has not been addressed.',
        'Dear Mr. Muhannad,    Please note that my colleague @Feryal Mithalouni agreed with @muhammed.reda during yesterday''s phone call that all alerts before the latest version of the new system is released on September 19, 2025, will be resolved manually by us. Therefore, please provide me with any alerts/work cases you are experiencing problems with so that we can resolve them.    As for any alerts after September 19, 2025, please provide them to us so we can forward them to the development department for follow-up.    With all thanks and appreciation,',
