(
        '19944',
        'World check list not return values during search',
        'we participate in data list of world check , when search today for famous name the system not return lists',
        'Dear @Dashti Mohammed,    As discussed during our meeting yesterday, since the issue is related to the version of Windows currently installed on your server (“Windows 12”), which is out of support from Microsoft, please be informed that to address the matter you have three available options:    1. Prepare a new VM with the same specifications as the current production application server, but with Windows 2019 installed. We will then proceed with installing our applications (AML & RBA) on it.    2. Upgrade or replace the current server. Please note that this is a high-risk option, and your IT team must ensure a full image backup is taken beforehand.    3. Prepare a new physical machine with the same or higher specifications than the current server, with Windows 2019 installed, to proceed with the installation of our applications.    Kindly review these options with your IT team and let us know if you have any questions or require further clarification.',
