        'Dears, Kindly Note that we are facing an issue with new AML Alerts not showing up after we''ve installed the latest release. your action ASAP please. regards.',
        'Based on our web session, kindly find the below status:    • Issue Reported by the customer: AML Alerts.    • Status: Solved.    • Problem description: AML alerts were not appearing in the system.    • Action Taken – recommended solution: Based on our web session, please be informed that a feature in the BankBI services was turned off after installing a new release, which caused the alerts to stop appearing in the system. After re-enabling this feature, the alerts are now appearing correctly.',
