(
        '19946',
        'Case Inquiry screen',
        'Please be informed that we are still facing an issue with the Case Inquiry screen, where users are unable to view client information. This issue has been occurring since 20-09-2025.  Although the problem gets resolved temporarily during the day, it reoccurs the following day. The issue is being monitored and addressed in real-time; however, it keeps reappearing daily.',
        'Dear @saifeddin.rasheed,    Please note that there is no issue with the Case Inquiry screen. The Username field reflects the officer who locked by the alert, not the one currently assigned to it. Additionally, a new report has been included in the latest release called:     • Performance User – Officer.     From this report, you can retrieve a complete record for any officer within a selected date range, as shown in the picture below:         Note: AML report permissions are currently granted only to seniors and managers. If you would like me to make this report accessible to officers as well, please let me know.    Regarding to the customer numbers (33694309 , 32943207) provided from your side, please note that the alerts are appearing in the system without any issues, as shown in the pictures below.    Kindly check and confirm.',
