        'ETL issue',
        'Dear Team  Yesterday extraction is not working and Bariso is  waiting for you to connect.Your usual swift  support is appreciated.',
        'Dear Bariso,    Based on our web session, kindly find below the status:      • Issue Reported by the customer: ETL issue.    • Status: Solved.    • Problem description: The ETL data extraction failed on September 29, 2025, due to a Windows maintenance task consuming system resources, which caused a conflict between the main ETL job and the Dashboard project job.    • Action Taken – recommended solution: Based on our web session, The issue was resolved by separating the Dashboard ETL job from the main ETL job. The main ETL job was then re-executed successfully for the dates of September 29 and 30, 2025.    Kindly note that the ETL jobs will remain under monitoring to ensure their stability.  Kindly check from your side and confirm to close this ticket.     Best Regards,',
