        'we have face the following error in our scheduled reports   Unable to connect to service WebiPlugin.WebiSession from server SRVBI.sgbsy.local:6400 via CMS osca:iiop://SRVBI.sgbsy.local:6400;SI_SESSIONID=3770110JWnsGPEvLhCvVZKAQfbP7u4l80yIPGl73,SI_TENANT_ID=0,SI_SERVER_LOGON_SESSION=1 (FWM 01006)',
        'Dear Manar,    After reviewing the scheduled report, I found that it has been running successfully every day, except for the instance on 24/09/2025 at 4 AM. At that time, the report failed but was successfully executed again later at 12:00 PM, as well as today, without any issues, as shown below.         Upon further investigation of the SAP BO logs for the Adaptive Job Server, I identified that the failure was caused by insufficient memory at that specific time, as shown below.  To help prevent similar issues in the future, kindly consider increasing the allocated RAM, and based on that, we will close this ticket.           Best Regards,',
