        'Dears,    Based on our web session, kindly find below the status:     • Issue Reported by the customer: Alert Issue – Al Furat Branch.     • Status: Solved.     • Problem description: Some alerts were appearing even though they had already been closed.    • Action Taken – recommended solution: Based on our web session, please note that the fourth alert related to Al Furat Branch was at the senior level and then had been closed. However, there was a mismatch in the workflow tables. After adjusting the steps for the work-cases, it is now functioning as expected.    Kindly check from your side and confirm so we can proceed with closing this ticket.',
