        'Based on our web session, please find below the required select statements:     Delta screening:    SELECT c.CUS_NUM  FROM PIO_AML_CUSTOMERS c  WHERE c.AML_SCENARIO_CODE IN (''777777'', ''888888'')   AND c.DAY_DATE =sysdate   AND EXISTS (   SELECT cus_num   FROM BI_ODS.CUSTOMER o   WHERE o.CUS_NUM = c.CUS_NUM   AND o.DATE_OPEN <> sysdate-1   and c.day_Date = sysdate   );     New Customers :     SELECT c.CUS_NUM  FROM PIO_AML_CUSTOMERS c  WHERE c.AML_SCENARIO_CODE IN (''777777'', ''888888'')   AND c.DAY_DATE =sysdate   AND EXISTS (   SELECT cus_num   FROM BI_ODS.CUSTOMER o   WHERE o.CUS_NUM = c.CUS_NUM   AND o.DATE_OPEN = sysdate-1   and c.day_Date = sysdate   );    Kindly note that these queries need to be executed on a daily basis in order to ensure accurate results.    Please check from your side and confirm so that we can proceed with closing this ticket.',
