(
        '20025',
        'Duplicate alerts on screening results',
        'Duplicate alerts on screening results',
        'Dear Shaza,    Based on our web session, please be informed that the large number of alerts is due to recent changes applied to the Free List.    Kindly note the following regarding the Free Lists and delta alerts:  When a delta occurs, the AML system compares the newly received list with the previous version and processes only the modified or newly added entries.  1. OFAC updates occur most frequently and can include dozens or even hundreds of new or modified names.  2. EU and UN updates are less frequent and generally smaller in size.    As a result, the number of records received by the AML system during each update may vary — ranging from a few entries to several hundred, depending on the scope of the changes.    Regarding the duplicate entries in the screening results, as my team leader @Braa AlSabaten mentioned in the attached email, we will update you as soon as the issue is resolved.',
