        'Based on our web session, please be informed that the issue is related to the work cases are being uploaded regarding the hit of the delta of the screening alerts for the Free Lists,     Kindly note the below regarding the free lists and the delta alerts :     When a delta occurs, the AML system compares the new list with the previous one and processes only the changed entries.    1- OFAC updates are the most frequent and can include dozens or even hundreds of new or changed names.    2- EU and UN updates are less frequent and usually smaller in size.    As a result, the number of records received in the AML system varies by update — from a few entries up to several hundred during major list changes.     Kindly check from your side and confirm to close this ticket.',
