        'Dear Mutasem,    Based on our web session, kindly find below the status:      • Issue Reported by the customer: BI_DWH Schema Storage Checkup.    • Status: Solved.    • Problem description: The JIB bank team referred to us regarding the below-listed tables, stating that these tables are consuming a significant amount of storage and are continuously growing. Based on the feedback from the Pio-Tech development team, these tables are related to the ODI JKM process (Journalizing Knowledge Module) — part of the old CDC mechanism that is no longer in use.    OWNER TABLE_NAME TOATAL_GB TABLE_GB INDEX_GB  BI_DWH J$PIO_ACCOUNTS_CDC_STAGING 295.255 295.255 0  BI_DWH J$PIO_CUSTOMERS_CDC_STAGING 24.03 24.03 0  BI_DWH J$PIO_LOANS_CDC_STAGING 23.509 23.509 0  BI_DWH J$PIO_MUR_TAB_CDC_STAGING 17.28 17.28 0  BI_DWH J$PIO_CUSTOMER_IMV_CDC_STAGING 12.396 12.396 0    • Action Taken – recommended solution: Based on our web session, kindly note that the issue was resolved by disabling the JKM process for these tables in the ODI ETL tool and truncating their data, as these tables are no longer in use.   Tomorrow morning, I will reconnect with you to ensure that the issue is resolved.  Kindly check from your side and confirm to close this ticket.     Best Regards,',
