        '20121',
        'Check AML Screening Alerts',
        'Regarding the watchlists, it has been more than 10 days since we last received any blacklist alerts.',
        'Dears,     Based on our web session, kindly find below the status:     Issue Reported by the customer: Check AML Screening Alerts.     Status: Done.     Problem description: There were no offline screening alerts generated for a specific date.     Action Taken – recommended solution: Based on our web session, please note that the issue occurred because the similarity process was stopped, which caused the offline screening alerts to be missing from 22nd September 2025 until today. However, after re-running the similarity process for the affected date range, the issue has been resolved, and the alerts are now functioning as expected, as shown in the picture below.    Note: Please do not stop the similarity process. It should remain running daily to ensure the alerts are generated as expected.    Kindly check from your side and confirm so we can proceed with closing this ticket.',
