        '20125',
        'Screening issues',
        'Dears    First of all, thank you for your cooperation during today’s testing. After reviewing the process for User1, User2, and Manager, please find our notes below    1.The rank should be set to 85 instead of 80.  2- New customer screening should be performed at least three times per day.  3- Delta screening should be executed twice daily.  4- The comment field is currently not editable.  5- The matching results appear to be empty.    In addition, please confirm whether it is possible to maintain the process between the maker and checker only, with the manager having view-only access to monitor the process through reports.',
        'Dear @Mohammad Al-Shaikh,    Thank you for your efforts in addressing the screening issues.  Kindly share the required modifications so we can proceed with implementing the updates to Bemo and the CSS. Additionally, we would appreciate it if you could provide the outlined email steps to apply them in our customer communications.    Dear @Alaa Hasan, @Alaa Haddad,     Please apply these modifications to the current release to ensure we do not encounter the same issues with other clients.',
