        'Exclude closed accounts',
        'Dears,    Based on our web session, please note that the modification of the customer status in the RBA report, specifically the “Customer Risk Score” report, has been completed by adding the statement provided from your side to the account query related to the data from the core banking system , and mapping it to our table.    Starting from tomorrow, please monitor the data in the report. Only customers with an “Active” status will be retrieved as per request. Kindly review the report tomorrow and share your feedback.',
