(
        '20132',
        'API failed request',
        'Please note that we tried to perform a screening on the corporate name using the fuzzy API, but we received a response of Something went wrong with status code “500”.  We need your advice if this applicable, I will attach the request and response for your review and investigation.    Your feedback is greatly appreciated.    Best Regards,',
        'Based on our web session, please be informed that I tested two API requests using the same customer name (“CHANGANSHIPPING &TECHNOLOGY”).      As shown in the attached file, the correct API request is different from the one you submitted, which caused the issue.    • First request: Used "minimumNameScore": "75" ? The request worked successfully and returned a valid response.  • Second request: Used "MinimumNameScore": "0" ? The server returned HTTP 500 (Internal Server Error).    After checking, the issue occurs because setting the MinimumNameScore to 0 is logically invalid.  The MinimumNameScore parameter defines the minimum similarity threshold between the searched name and the matched names in the watchlist.  When it’s set to 0, the system interprets it as “no similarity limit,” which can cause unexpected behavior or overload during the matching process — leading to an internal server error.    Recommendation:  To avoid such errors, MinimumNameScore should always be assigned a valid matching threshold (for example, 75 or higher) to ensure meaningful and stable search results.       Kindly check from your side and confirm to close this ticket.',
        '2025-10-14T00:00:00.000Z'::timestamptz,
        '2025-10-15T00:00:00.000Z'::timestamptz,
        '015a7170-65d3-490b-bd00-2c41faabf8f9'::uuid,
