        '20136',
        'Check release issues',
        'Dear Mohammed,    Please find attached a list of issues identified in the system following the recent release.    Kindly review the reported points and provide your support in resolving them at your earliest convenience.',
        'Dears,         Based on our web session, please note the following updates regarding the issues reported from your side:         Officers taking final action: After checking the workflow and the related scenario, we found no issue in the system itself. However, after consulting our QA team, they confirmed that this occurs when the officer clicks the action button multiple times. Each click opens a new pop-up window, and upon saving and closing each one, the alert moves to the next level.       System language requirement: Please note that the system requires selecting a language only during the first login. For subsequent logins, it will automatically sign in without prompting for a language selection.       Locked alerts: In the new version, a new tab called “Unlocked” has been added in the Re-assign screen. This tab allows you to unlock any alerts that were previously locked by any user, as shown in the picture below:                 Alerts locked when closed: We have updated the alerts that were locked by specific users. In addition, we have modified the related procedure to ensure that:  · When a new alert is opened with current step ''1'' and locked by a user while viewing only, it will be automatically unlocked afterward.    · If an alert is closed with current step ''4'', it will also be automatically unlocked.    Kindly review the above points and confirm so we can proceed with closing this ticket.',
