        'Dear @Oula Michel,    Based on our web session, kindly find below the status:    Issue Reported by the customer: Issues on suspected customers.       Status: Solved.    Problem description: Issues were observed on the Suspected Customers screen.  Action Taken – recommended solution: Based on our web session, please note that the issue was identified where closed alerts appeared for all users and branches during the period from 1st January 2024 to 31st December 2024. This occurred due to invalid step values in the workflow tables that did not match the current step. After identifying and correcting the mismatched workflow steps, the issue has been resolved and the functionality is now working as expected.  Additionally, the locked alerts have been successfully transferred from user ''Avana'' to user ''Ahmed Issa'', as requested.  Kindly check from your side and confirm so we can proceed with closing this ticket.',
