(
        '20205',
        'Blacklist search issue',
        'Am sending his email to inform you that name (ABD EL KADER MAHMOUD MOHAMED EL SAYED) no results will be found when we search for the full name on BANKPI,   However, if we removed the 3rd syllable (MOHAMED) results will be found, and as attached please check his issue and revert .',
        'Dears,         Based on our web session, kindly find below the status:         Issue Reported by the customer: Blacklist search issue.       Status: No issue.       Problem description: The user was unable to find the name “ABD EL KADER MAHMOUD MOHAMED EL SAYED” when searching in the Watchlist Checker screen.  Action Taken – recommended solution: Based on our web session, please note that there is no issue with the search functionality. The name in question appears in the list with only three parts instead of four; therefore, when the search is performed using the four-parts version, no results are returned. Furthermore, the “Full Name Native” field is empty in the list, which also impacts the search results. This is due to the search criteria applied in the Manual Checker screen, which operate as follows:  The system first attempts to search using AKA First Name || AKA Last Name.  If both of these fields are null, it proceeds to search using the AKA Full Name.  If this field is also null, the system then searches using the Full Name Native.  If all the above are null, it finally searches using First Name || Last Name.  Please rest assured that the search functionality is working as designed according to the defined criteria.',
