        'Dears,    Based on our meeting, here is the query related to add discounting LC    SELECT   DW_FSI_D_LC_DISCOUNTING.AS_OF_DATE,  DW_FSI_D_LC_DISCOUNTING.ORG_UNIT_ID,  DW_FSI_D_LC_DISCOUNTING.ISO_CURRENCY_CD,  DW_FSI_D_LC_DISCOUNTING.CUSTOMER_ID,  --DW_FSI_D_LC_DISCOUNTING.START_DATE,  DW_FSI_D_LC_DISCOUNTING.ISSUE_DATE,  --DW_FSI_D_LC_DISCOUNTING.ORIGINATION_DATE,  DW_FSI_D_LC_DISCOUNTING.MATURITY_DATE,  DW_FSI_D_LC_DISCOUNTING.GL_ACCOUNT_ID,  DW_FSI_D_LC_DISCOUNTING.APPLICATION_NUMBER,  DW_FSI_D_LC_DISCOUNTING.PRINCIPAL_OUTSTANDING,   DW_FSI_D_LC_DISCOUNTING.PRINCIPAL_OUTSTANDING_JOD  FROM OFSAEPM.DW_FSI_D_LC_DISCOUNTING , OFSAEPM.DW_FSI_D_LC_APPLICATIONS  WHERE DW_FSI_D_LC_APPLICATIONS.AS_OF_DATE=''30-SEP-2025''  AND DW_FSI_D_LC_DISCOUNTING.AS_OF_DATE=''30-SEP-2025''  AND DW_FSI_D_LC_APPLICATIONS.APPLICATION_NUMBER=DW_FSI_D_LC_DISCOUNTING.APPLICATION_NUMBER  AND NVL(DW_FSI_D_LC_APPLICATIONS.ACCOUNT_83507,0)<>0    Thanks,',
        'Based on our web session, kindly find below the status:     • Issue Reported by the customer: Apply LC discounting request.     • Status: New request has been applied.     • Problem description: New request.     • Action Taken – recommended solution: As per your request, discounted LCs have been incorporated into the CRS report based on the criteria outlined below.  SELECT  DW_FSI_D_LC_DISCOUNTING.AS_OF_DATE,  DW_FSI_D_LC_DISCOUNTING.ORG_UNIT_ID,  DW_FSI_D_LC_DISCOUNTING.ISO_CURRENCY_CD,  DW_FSI_D_LC_DISCOUNTING.CUSTOMER_ID,  DW_FSI_D_LC_DISCOUNTING.ISSUE_DATE,  DW_FSI_D_LC_DISCOUNTING.MATURITY_DATE,  DW_FSI_D_LC_DISCOUNTING.GL_ACCOUNT_ID,  DW_FSI_D_LC_DISCOUNTING.APPLICATION_NUMBER,  DW_FSI_D_LC_DISCOUNTING.PRINCIPAL_OUTSTANDING,  DW_FSI_D_LC_DISCOUNTING.PRINCIPAL_OUTSTANDING_JOD  FROM OFSAEPM.DW_FSI_D_LC_DISCOUNTING , OFSAEPM.DW_FSI_D_LC_APPLICATIONS  WHERE DW_FSI_D_LC_APPLICATIONS.AS_OF_DATE=''30-SEP-2025''  AND DW_FSI_D_LC_DISCOUNTING.AS_OF_DATE=''30-SEP-2025''  AND DW_FSI_D_LC_APPLICATIONS.APPLICATION_NUMBER=DW_FSI_D_LC_DISCOUNTING.APPLICATION_NUMBER  AND NVL(DW_FSI_D_LC_APPLICATIONS.ACCOUNT_83507,0)<>0    Kindly check from your side and confirm to close this ticket.',
