        '20276',
        'Check AML alerts issue',
        'Check AML alerts issue',
        'Dear @azher,     Based on our web session, kindly find below the status:     Issue Reported by the customer: Check AML alert issue.     Status: Solved.     Problem description: Some alerts were not visible to users within the same branch, and certain work cases were able to be closed with a final status.     Action Taken – recommended solution: Based on our web session, please note the following based on the notes:    Users Taking Final Status: The issue occurred because the Approval Flag was enabled for the related scenario, which allowed users to apply the final status instead of forwarding the alert. We updated the scenario configuration, and it is now functioning as expected. Users can no longer finalize the alert at this step, as shown in the picture below:          Alerts Not Visible to Branch Users: The alerts were locked by a specific user (Mustafa), which prevented other users in the same branch from viewing them. After removing the lock, the alerts are now visible to all relevant users in the branch view is consistent for everyone, as shown in the picture below:       Kindly check from your side and confirm so we can proceed with closing this ticket.',
