        '20312',
        'Application fatca Production Link need license code',
        'Dear .Raed ,   AS per your request kindly find the below function script     CREATE OR REPLACE FUNCTION BI_ODS.init_Snap_Date   RETURN Date  IS   Snape_Date date;   pre_bank_date date;   v_error_code pio_dwh_err.err_code%TYPE;   v_error_msg pio_dwh_err.err_msg%TYPE;   v_FileHandle sys.UTL_FILE.FILE_TYPE;   v_NewLine NVARCHAR2 (32767); -- Input line   Customer_Arrray apex_application_global.vc_arr2;   V_DAY_DATE DATE; --:=TO_CHAR(TO_DATE(SYSDATE,''DD/MM/YYYY''));   V_END_EXECUTE varchar2 (50);   V_SQL_DESCRIPTION VARCHAR2 (300);   V_SQL_CODE NUMBER;   V_STATUS_CODE NUMBER;   V_FILE_RECORD NUMBER := 1;   V_EXISIT_DATE NUMBER := 0;   p_FileDir VARCHAR2 (100) := ''FATCA'';   p_FileName VARCHAR2 (100) := ''CUST4.txt'';  BEGIN   v_FileHandle :=   UTL_FILE.FOPEN_NCHAR (p_FileDir,   p_FileName,   ''r'',   32767);   UTL_FILE.GET_LINE_NCHAR (v_FileHandle, v_NewLine, 32767);   Customer_Arrray := apex_util.string_to_table (v_NewLine, '';'');   V_DAY_DATE := TO_DATE (Customer_Arrray (5), ''YYYYMMDD'');     UTL_FILE.FCLOSE (v_FileHandle);     --select max(pre_bank_date)   --into pre_bank_Date from branch;   --snape_date := pre_bank_date;   --return Snape_Date;     RETURN V_DAY_DATE;  --RETURN TRUNC(SNAP_DATE(818,1));  EXCEPTION   WHEN OTHERS   THEN   UTL_FILE.FCLOSE (v_FileHandle);   v_error_code := -SQLCODE;   v_error_msg := SUBSTR (SQLERRM (SQLCODE), 1, 100);     INSERT INTO pio_dwh_err   VALUES (SYSDATE,   818,   1,   ''FILL_UNB_CUSTOMER'',   v_error_code,   v_error_msg);  END;  /',
