        'AML Screening Tool Turns off due to session timeout on the server',
        'AML Screening Tool Turns off due to session timeout on the server,',
        'I hope my email finds you well,  After investigating the recent issue where the AML Screening Tool was shutting down, we identified that the cause was related to session timeouts on the server,  Following updates to the server’s group policy and adjustments to session time limits as follows:  • Set time limit for active but idle Remote Desktop Services sessions ? Never as it was 15 mins  • Set time limit for disconnected sessions ? Never   • End session when time limits are reached ? Disabled  We tested the tool for over two hours, and I am pleased to confirm that it has been stable and fully operational, without any crashes or unexpected shutdowns, as shown in the below screenshot,     Kindly consider applying these settings in future server policy updates to prevent this issue from recurring.  Kindly confirm from your side and regarding this we will proceed with closing this ticket   ----------------    Dears,    Please note that we will proceed with closing this ticket, and we will open a new one once we receive your response regarding our previous discussion.',
